<script setup lang="ts">
import {computed,nextTick,onMounted,onBeforeUnmount,ref} from 'vue'
import {useRoute} from 'vue-router'
import {Plus,Minus,Send,ArrowUpRight,Check,X} from 'lucide-vue-next'
import BlueRobot from './BlueRobot.vue'
import QueryTable from './QueryTable.vue'
import request from '@/utils/request'

type Row=Record<string,any>
const route=useRoute(),open=ref(false),busy=ref(false),loading=ref(false),error=ref('')
const catalog=ref<Row>({skills:[],model:{}}),messages=ref<Row[]>([]),question=ref(''),selected=ref(''),session=ref(''),previous=ref('')
const feed=ref<HTMLElement>(),composer=ref<HTMLTextAreaElement>(),launcher=ref<HTMLButtonElement>()
const position=ref({x:0,y:0}),ready=ref(false),dragging=ref(false)
let pointer:number|null=null,start={x:0,y:0,left:0,top:0},moved=false,previousFocus:HTMLElement|null=null
const names:Row={PENDING:'等待确认',SUCCEEDED:'已完成',CLARIFICATION:'待补充',FAILED:'执行失败',CANCELLED:'已取消',EXPIRED:'已过期',STALE:'需重新核对'}
const panelStyle=computed(()=>({right:'16px',bottom:'16px'}))
const mode=computed(()=>catalog.value.model.mode==='remote'?(catalog.value.model.configured?'模型已连接':'等待模型配置'):'本地技能模式')
function clamp(){position.value={x:Math.max(8,Math.min(position.value.x,window.innerWidth-88)),y:Math.max(8,Math.min(position.value.y,window.innerHeight-108))}}
function save(){try{sessionStorage.setItem('mes-blue-position',JSON.stringify(position.value))}catch{}}
function down(e:PointerEvent){if(e.button!==0)return;pointer=e.pointerId;start={x:e.clientX,y:e.clientY,left:position.value.x,top:position.value.y};moved=false;dragging.value=true;launcher.value?.setPointerCapture(e.pointerId)}
function move(e:PointerEvent){if(pointer!==e.pointerId)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.hypot(dx,dy)>5)moved=true;if(moved){position.value={x:start.left+dx,y:start.top+dy};clamp()}}
function up(e:PointerEvent){if(pointer!==e.pointerId)return;pointer=null;dragging.value=false;if(launcher.value?.hasPointerCapture(e.pointerId))launcher.value.releasePointerCapture(e.pointerId);save()}
async function show(){if(moved){moved=false;return}previousFocus=document.activeElement as HTMLElement;open.value=true;await nextTick();composer.value?.focus();if(!catalog.value.skills.length)await load()}
function close(){open.value=false;nextTick(()=>{if(previousFocus?.isConnected)previousFocus.focus();else launcher.value?.focus()})}
async function load(){loading.value=true;error.value='';try{catalog.value=await request.get('/agent/skills')}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function scroll(){await nextTick();feed.value?.scrollTo({top:feed.value.scrollHeight,behavior:'smooth'})}
async function add(run:Row){const i=messages.value.findIndex(m=>m.id===run.id);if(i<0)messages.value.push(run);else messages.value[i]=run;await scroll()}
async function ask(){if(busy.value||!question.value.trim())return;busy.value=true;error.value='';try{const run=await request.post<Row>('/agent/messages',{question:question.value.trim(),skillId:selected.value,previousSkill:previous.value,...(session.value?{sessionId:session.value}:{})},{timeout:35000});if(run.reply?.sessionId){session.value=run.reply.sessionId;previous.value=run.skill_id}await add(run);question.value=''}catch(e:any){error.value=e.message}finally{busy.value=false;await nextTick();composer.value?.focus()}}
async function action(url:string){if(busy.value)return;busy.value=true;error.value='';try{await add(await request.post<Row>(url))}catch(e:any){error.value=e.message}finally{busy.value=false}}
function choose(skill:Row){selected.value=skill.id;question.value=skill.example;composer.value?.focus()}
function reset(){if(busy.value)return;messages.value=[];question.value='';selected.value='';session.value='';previous.value='';error.value='';composer.value?.focus()}
function keys(e:KeyboardEvent){if(e.key==='Escape'&&open.value){e.preventDefault();close()}}
function trap(e:KeyboardEvent){if(e.key!=='Tab')return;const items=Array.from((e.currentTarget as HTMLElement).querySelectorAll<HTMLElement>('button:not(:disabled),a[href],textarea:not(:disabled),select:not(:disabled),summary')).filter(el=>el.getClientRects().length);const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}
onMounted(()=>{position.value={x:window.innerWidth-108,y:window.innerHeight-138};try{const saved=JSON.parse(sessionStorage.getItem('mes-blue-position')||'null');if(Number.isFinite(saved?.x)&&Number.isFinite(saved?.y))position.value=saved}catch{}clamp();ready.value=true;window.addEventListener('resize',clamp);window.addEventListener('keydown',keys)})
onBeforeUnmount(()=>{window.removeEventListener('resize',clamp);window.removeEventListener('keydown',keys)})
</script>
<template>
<Teleport to="body">
 <button v-if="ready&&!open&&route.path!=='/assistant'" ref="launcher" class="blue-launcher" :class="{'is-dragging':dragging}" :style="{left:position.x+'px',top:position.y+'px'}" aria-label="打开小蓝制造协作助手，可拖动调整位置" aria-haspopup="dialog" :aria-expanded="open" @pointerdown="down" @pointermove="move" @pointerup="up" @pointercancel="up" @click="show" @keydown.enter="moved=false" @keydown.space="moved=false">
  <BlueRobot/><span class="blue-name">小蓝 · 业务助手</span>
 </button>
 <Transition name="blue-panel">
 <section v-if="open" class="blue-chat" :style="panelStyle" role="dialog" aria-label="小蓝制造协作助手" @keydown="trap">
  <header class="blue-header"><div class="blue-avatar"><BlueRobot/></div><div class="blue-title"><div><strong>小蓝</strong><span>制造协作助手</span></div><p><i></i>{{mode}} · 为你连接业务数据</p></div><button :disabled="busy" aria-label="新会话" title="新会话" @click="reset"><Plus :size="19"/></button><button aria-label="收起小蓝" title="收起" @click="close"><Minus :size="20"/></button></header>
  <div ref="feed" class="blue-feed" role="log" aria-live="polite" :aria-busy="busy">
   <div v-if="!messages.length" class="blue-welcome"><div class="welcome-robot"><BlueRobot/></div><h2>你好，我是小蓝。</h2><p>查库存、看缺料、追工单，<br/>把生产现场的事，交给我一起处理。</p><div class="blue-shortcuts"><button v-for="skill in catalog.skills" :key="skill.id" :disabled="busy" @click="choose(skill)">{{skill.name}}<ArrowUpRight :size="14"/></button></div><p v-if="loading" class="blue-hint">正在连接业务技能…</p><button v-else-if="!catalog.skills.length" class="blue-retry" @click="load">重新加载技能</button></div>
   <article v-for="run in messages" :key="run.id" class="blue-turn"><div class="blue-question">{{run.question}}</div><div class="blue-answer"><div class="answer-heading"><strong>小蓝</strong><span>{{names[run.status]||run.status}}</span></div><p>{{run.reply.summary}}</p><p v-for="c in run.reply.query?.clarifications||[]" :key="c">{{c}}</p>
    <template v-if="run.reply.data"><p class="blue-evidence">{{run.reply.data.evidence}}<br v-if="run.reply.data.updatedAt"/>{{run.reply.data.updatedAt}}</p><QueryTable :rows="run.reply.data.rows||[]"><template #default="{row}"><button v-if="run.reply.canPropose&&row.status!=='CONFIRMED'" :disabled="busy" class="blue-retry" @click="action('/agent/proposals/'+row.material_id)">生成确认任务</button></template></QueryTable><template v-if="run.reply.data.reports"><h4>报工记录</h4><QueryTable :rows="run.reply.data.reports"/><h4>过程检验</h4><QueryTable :rows="run.reply.data.inspections||[]"/></template><details v-if="run.reply.data.sources"><summary>查看来源流水</summary><QueryTable :rows="run.reply.data.sources.slice(0,200)"/></details></template>
    <div v-if="run.reply.preview" class="blue-confirm"><strong>补货建议核对</strong><p>{{run.reply.preview.material_name}} · {{run.reply.preview.material_code}}</p><p>当前库存：{{run.reply.preview.current_quantity}} {{run.reply.preview.unit}}<br/>安全库存：{{run.reply.preview.safety_stock}} {{run.reply.preview.unit}}<br/>建议补货：{{run.reply.preview.suggested_quantity}} {{run.reply.preview.unit}}</p><div v-if="run.status==='PENDING'" class="confirm-actions"><button :disabled="busy" @click="action('/agent/runs/'+run.id+'/confirm')"><Check :size="14"/>确认登记建议</button><button :disabled="busy" @click="action('/agent/runs/'+run.id+'/cancel')"><X :size="14"/>取消</button></div></div>
   </div></article><p v-if="busy" class="blue-thinking">小蓝正在处理你的任务<span>…</span></p>
  </div>
  <div v-if="error" class="blue-error" role="alert">{{error}}</div>
  <form class="blue-composer" @submit.prevent="ask"><label class="blue-skill">当前技能<select v-model="selected" :disabled="busy"><option value="">自动识别任务</option><option v-for="skill in catalog.skills" :key="skill.id" :value="skill.id">{{skill.name}}</option></select></label><label for="blue-question" class="sr-only">告诉小蓝你的任务</label><textarea id="blue-question" ref="composer" v-model="question" :disabled="busy" rows="2" maxlength="1200" placeholder="告诉小蓝，你想完成什么…" @keydown.ctrl.enter.prevent="ask"></textarea><div class="blue-send-row"><span>{{question.length}}/1200 · Ctrl+Enter</span><button :disabled="busy||!question.trim()||loading" type="submit"><Send :size="16"/>{{busy?'处理中':'发送'}}</button></div></form>
  <footer class="blue-footer"><span>业务写入需核对确认</span><router-link to="/assistant" @click="close">完整工作台 <ArrowUpRight :size="12"/></router-link></footer>
 </section>
 </Transition>
</Teleport>
</template>
<style scoped>
.blue-launcher{position:fixed;z-index:1100;width:88px;height:108px;padding:0;border:0;background:transparent;cursor:grab;touch-action:none;user-select:none;display:flex;flex-direction:column;align-items:center;color:#5085a3}.blue-launcher:focus-visible{outline:2px solid #4ca9e1;outline-offset:4px;border-radius:22px}.blue-launcher.is-dragging{cursor:grabbing}.blue-launcher .blue-robot{width:80px;height:91px;pointer-events:none}.blue-name{font-size:10px;white-space:nowrap;background:#f4fbffdd;border:1px solid #d5ebf8;border-radius:12px;padding:2px 8px;box-shadow:0 3px 12px #4b9ed31a}.blue-chat{position:fixed;z-index:1101;width:min(500px,calc(100vw - 32px));height:min(720px,calc(100dvh - 32px));display:flex;flex-direction:column;border:1px solid #c5e0f2;border-radius:22px;overflow:hidden;background:#f7fbff;box-shadow:0 18px 65px #28587e30;color:#436f8c;font-family:inherit;font-size:13px}.blue-header{display:flex;align-items:center;gap:9px;padding:13px 16px;background:linear-gradient(110deg,#e9f8ff,#dfecff);border-bottom:1px solid #cee3f3;flex-shrink:0}.blue-avatar{width:43px;height:51px;flex-shrink:0}.blue-title{flex:1;min-width:0}.blue-title>div{display:flex;align-items:baseline;gap:9px}.blue-title strong{font-size:20px;color:#2d6689}.blue-title span{font-size:11px;color:#7294ab}.blue-title p{font-size:10px;color:#7595aa;margin:5px 0 0;display:flex;align-items:center;gap:5px}.blue-title i{width:6px;height:6px;border-radius:50%;background:#52bca8}.blue-header>button{display:grid;place-items:center;width:30px;height:32px;color:#7198af;border:0;background:transparent;border-radius:8px}.blue-header>button:hover{background:#cbe4f5}.blue-feed{flex:1;min-height:0;overflow:auto;padding:20px 17px;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:#bfddeb transparent}.blue-welcome{text-align:center;padding:0 0 12px}.welcome-robot{width:98px;height:114px;margin:0 auto 12px}.blue-welcome h2{font-size:21px;font-weight:650;color:#3d789d;margin:0 0 12px}.blue-welcome>p{font-size:13px;line-height:1.9;color:#8aa3b7;margin:0 0 22px}.blue-shortcuts{display:grid;grid-template-columns:1fr 1fr;gap:9px}.blue-shortcuts button{display:flex;align-items:center;justify-content:space-between;text-align:left;gap:8px;padding:11px 10px;border:1px solid #cfe4f4;background:#edf7ff;border-radius:11px;color:#628fa9;font-size:12px}.blue-shortcuts button:hover{background:#dcefff;border-color:#9acde9}.blue-turn+.blue-turn{margin-top:20px}.blue-question{margin-left:auto;max-width:90%;width:fit-content;background:#dcefff;border-radius:14px 14px 3px 14px;padding:10px 13px;white-space:pre-wrap;overflow-wrap:anywhere}.blue-answer{margin-top:13px;padding:13px;background:white;border:1px solid #dfedf6;border-radius:3px 14px 14px 14px;min-width:0;overflow-wrap:anywhere}.blue-answer>p{line-height:1.8;margin:10px 0;white-space:pre-wrap}.answer-heading{display:flex;align-items:center;gap:8px}.answer-heading span{font-size:10px;background:#e7f5f3;color:#4d9a8d;padding:2px 6px;border-radius:5px}.blue-answer .blue-evidence{font-size:10px;color:#8b9eaf}.blue-answer h4{margin:12px 0 7px}.blue-confirm{padding:12px;border:1px solid #badbf0;background:#f0f8ff;border-radius:10px;margin-top:12px}.blue-confirm p{margin:8px 0;line-height:1.8}.confirm-actions{display:flex;gap:8px;flex-wrap:wrap}.confirm-actions button{display:flex;align-items:center;gap:4px;border:1px solid #bbd8ed;border-radius:7px;padding:7px;background:white}.confirm-actions button:first-child{background:#448ec2;color:white}.blue-thinking{font-size:12px;color:#739db7;margin:15px 0}.blue-error{flex-shrink:0;max-height:75px;overflow:auto;padding:9px 17px;background:#fff1ef;color:#ab574e;font-size:12px}.blue-composer{padding:12px 16px;background:#f0f7ff;border-top:1px solid #daeaf7;flex-shrink:0}.blue-skill{display:flex;align-items:center;gap:9px;font-size:11px;color:#89a2b4;margin-bottom:9px}.blue-skill select{max-width:75%;border:1px solid #cfe4f2;background:white;border-radius:8px;padding:5px 7px;color:#618ba5;font:inherit}.blue-composer textarea{width:100%;resize:none;border:1px solid #a8d3ed;border-radius:11px;background:white;padding:11px 12px;color:#385f7d;font:inherit;line-height:1.6;min-height:72px;box-shadow:0 0 0 2px #e2f1fb;outline:none}.blue-composer textarea:focus{border-color:#5aaddd;box-shadow:0 0 0 3px #cfeafb}.blue-composer textarea::placeholder{color:#9eb4c4}.blue-send-row{display:flex;align-items:center;justify-content:space-between;margin-top:9px}.blue-send-row>span{font-size:10px;color:#98adbc}.blue-send-row button{display:flex;align-items:center;gap:6px;border:0;background:linear-gradient(110deg,#74c5df,#78a9df);border-radius:9px;padding:8px 13px;color:white;font-size:12px}.blue-chat button:disabled{opacity:.5;cursor:default}.blue-footer{display:flex;align-items:center;justify-content:space-between;padding:10px 16px;font-size:10px;border-top:1px solid #e2eef7;color:#98adbc;flex-shrink:0}.blue-footer a{display:flex;align-items:center;gap:4px;color:#638fa9}.blue-retry{color:#3889b9;font-size:12px}.blue-panel-enter-active,.blue-panel-leave-active{transition:opacity .18s,transform .18s}.blue-panel-enter-from,.blue-panel-leave-to{opacity:0;transform:translateY(15px) scale(.97)}@media(max-width:540px){.blue-chat{right:8px!important;bottom:8px!important;width:calc(100vw - 16px);height:min(720px,calc(100dvh - 16px));border-radius:18px}.blue-header{padding:10px 12px}.blue-feed{padding:16px 13px}.welcome-robot{width:82px;height:96px}.blue-welcome h2{font-size:19px}.blue-welcome>p{margin-bottom:16px}}@media(prefers-reduced-motion:reduce){.blue-panel-enter-active,.blue-panel-leave-active{transition:none}}
</style>
